import app from 'flarum/common/app';
import { invalidate } from './widgetData';

/** An event as the views use it: one occurrence of a calendar-events resource (EventResource). */

const api = path => app.forum.attribute('apiUrl') + path;
export const base = () => app.forum.attribute('baseUrl');

/** A JSON:API resource object, as the calendar resources send them. */

const toCategory = r => ({
  id: Number(r.id),
  ...r.attributes
});

/** Turn one calendar-events resource into the CalEvent the views use. */
function toEvent(r, included = []) {
  const find = rel => {
    const ref = r.relationships?.[rel]?.data;
    return ref ? included.find(i => i.type === ref.type && i.id === ref.id) : undefined;
  };
  const user = find('user');
  const category = find('category');
  const {
    occurrences,
    ...attrs
  } = r.attributes;
  return {
    ...attrs,
    id: Number(r.id),
    occurrence: null,
    category: category ? toCategory(category) : null,
    author: user ? {
      id: Number(user.id),
      username: user.attributes.username,
      displayName: user.attributes.displayName,
      avatarUrl: user.attributes.avatarUrl
    } : null
  };
}

/** A listed series becomes one CalEvent per occurrence inside the window, sorted by start. */
function toOccurrences(doc) {
  const rows = doc.data;
  const events = [];
  rows.forEach(r => {
    const event = toEvent(r, doc.included);
    (r.attributes.occurrences || []).forEach(o => {
      events.push({
        ...event,
        occurrence: o.occurrence,
        start: o.start,
        end: o.end,
        googleUrl: o.googleUrl
      });
    });
  });
  return events.sort((a, b) => a.start.localeCompare(b.start));
}
const widget = (name, query = {}) => {
  const qs = new URLSearchParams();
  Object.entries(query).forEach(([k, v]) => {
    if (v !== undefined) qs.set('filter[' + k + ']', String(v));
  });
  const s = qs.toString();
  return app.request({
    method: 'GET',
    url: api('/calendar-widgets/' + name + (s ? '?' + s : ''))
  }).then(r => r.data);
};
export function onThisDay(limit = 6) {
  return widget('memories', {
    limit
  });
}
export function celebrations() {
  return widget('celebrations');
}

/** Absolute URL for a server path the API handed us (e.g. an .ics path). */
export const abs = path => base().replace(/\/$/, '') + '/' + path.replace(/^\//, '');
export const feedUrl = () => abs('calendar/feed.ics');
export function userActivity(userId) {
  return widget('activity', {
    user: userId
  });
}
export function forumPulse(opts = {}) {
  return widget('pulse', opts);
}
export function listEvents(from, to, category) {
  const qs = new URLSearchParams({
    'filter[from]': from.toISOString(),
    'filter[to]': to.toISOString()
  });
  if (category) qs.set('filter[category]', category);
  return Promise.all([app.request({
    method: 'GET',
    url: api('/calendar-events?' + qs.toString())
  }), listCategories()]).then(([doc, categories]) => ({
    data: toOccurrences(doc),
    categories
  }));
}
export function showEvent(id) {
  return app.request({
    method: 'GET',
    url: api('/calendar-events/' + id)
  }).then(doc => toEvent(doc.data, doc.included));
}
export function saveEvent(attrs, id) {
  return app.request({
    method: id ? 'PATCH' : 'POST',
    url: api('/calendar-events' + (id ? '/' + id : '')),
    body: {
      data: {
        type: 'calendar-events',
        ...(id ? {
          id: String(id)
        } : {}),
        attributes: attrs
      }
    }
  }).then(doc => {
    invalidate('events:');
    return toEvent(doc.data, doc.included);
  });
}

/** Start the comment thread for an event that has none. */
export function startDiscussion(id) {
  return app.request({
    method: 'POST',
    url: api('/calendar-events/' + id + '/discussion')
  }).then(doc => {
    invalidate('events:');
    return toEvent(doc.data, doc.included);
  });
}
export function deleteEvent(id) {
  return app.request({
    method: 'DELETE',
    url: api('/calendar-events/' + id)
  }).then(r => {
    invalidate('events:');
    return r;
  });
}
export function rsvp(id, status) {
  return app.request({
    method: 'POST',
    url: api('/calendar-events/' + id + '/rsvp'),
    body: {
      data: {
        attributes: {
          status
        }
      }
    }
  }).then(doc => {
    invalidate('events:');
    return doc.data.attributes.rsvp;
  });
}
export function listCategories() {
  return app.request({
    method: 'GET',
    url: api('/calendar-categories')
  }).then(doc => doc.data.map(toCategory));
}
export function saveCategory(attrs, id) {
  return app.request({
    method: id ? 'PATCH' : 'POST',
    url: api('/calendar-categories' + (id ? '/' + id : '')),
    body: {
      data: {
        type: 'calendar-categories',
        ...(id ? {
          id: String(id)
        } : {}),
        attributes: attrs
      }
    }
  }).then(doc => toCategory(doc.data));
}
export function deleteCategory(id) {
  return app.request({
    method: 'DELETE',
    url: api('/calendar-categories/' + id)
  });
}
flarum.reg.add('ernestdefoe-calendar', 'common/api', { base: base,onThisDay: onThisDay,celebrations: celebrations,abs: abs,feedUrl: feedUrl,userActivity: userActivity,forumPulse: forumPulse,listEvents: listEvents,showEvent: showEvent,saveEvent: saveEvent,startDiscussion: startDiscussion,deleteEvent: deleteEvent,rsvp: rsvp,listCategories: listCategories,saveCategory: saveCategory,deleteCategory: deleteCategory, });